import { useEffect } from "react";

import CoppelPageLayout from "@/components/CoppelPageLayout";
import ULThemeCard from "@/components/ULThemeCard";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushPageView } from "@/utils/helpers/dataLayerUtils";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import Header from "./components/Header";
import MfaPushWelcomeForm from "./components/MfaPushWelcomeForm";
import { useMfaPushWelcomeManager } from "./hooks/useMfaPushWelcomeManager";

function MfaPushWelcomeScreen() {
  // Extracting attributes from hook made out of MfaPushWelcome instance of Auth0 React ACUL SDK
  const { texts, locales, mfaPushWelcome } = useMfaPushWelcomeManager();

  applyAuth0Theme(mfaPushWelcome);
  document.title = texts?.pageTitle || locales.page.title;

  useEffect(() => {
    const canal = getCanalByClientId();
    pushPageView(
      "/protege-tu-cuenta/auth0",
      "Protege tu cuenta - Auth0 ",
      canal
    );
  }, []);

  return (
    <CoppelPageLayout
      className="theme-universal"
      pageTitle={locales?.page?.title}
      mainAriaLabel={locales?.header?.description}
    >
      <ULThemeCard className="w-full max-w-[400px] gap-0">
        <Header />
        <MfaPushWelcomeForm />
      </ULThemeCard>
    </CoppelPageLayout>
  );
}

export default MfaPushWelcomeScreen;
