import { useEffect } from "react";

import ULThemeCard from "@/components/ULThemeCard";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushMfaSmsChallengePageView } from "@/utils/helpers/dataLayerUtils";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import CoppelPageLayout from "../../components/CoppelPageLayout";

import Footer from "./components/Footer";
import Header from "./components/Header";
import MfaSmsChallengeForm from "./components/MfaSmsChallengeForm";
import { useMfaSmsChallengeManager } from "./hooks/useMfaSmsChallengeManager";

function MfaSmsChallengeScreen() {
  // Extracting attributes from hook made out of MfaSmsChallenge instance of Auth0 React ACUL SDK
  const { mfaSmsChallenge, texts, locales } = useMfaSmsChallengeManager();

  applyAuth0Theme(mfaSmsChallenge);
  document.title = texts?.pageTitle || locales?.pageTitle;

  useEffect(() => {
    const isEnrollmentVerify = window.location.pathname.includes(
      "mfa-sms-enrollment-verify"
    );
    const canal = getCanalByClientId() || "Coppel.com";

    if (isEnrollmentVerify) {
      pushMfaSmsChallengePageView(
        "/protege-tu-cuenta/sms-codigo",
        "Proteje tu cuenta - SMS código",
        canal
      );
    } else {
      pushMfaSmsChallengePageView(
        "/protege-tu-cuenta/celular",
        "Protege tu cuenta - Celular",
        canal
      );
    }
  }, []);

  return (
    <CoppelPageLayout
      className="theme-universal"
      pageTitle={texts?.pageTitle || locales?.pageTitle}
    >
      <div className="w-full flex justify-center items-start md:items-center min-h-[calc(100vh-118px)] py-8 md:py-0">
        <ULThemeCard className="w-full max-w-[400px] gap-0">
          <Header />
          <MfaSmsChallengeForm />
          <Footer />
        </ULThemeCard>
      </div>
    </CoppelPageLayout>
  );
}

export default MfaSmsChallengeScreen;
