import ULThemeLink from "@/components/ULThemeLink";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushClicHipervinculo } from "@/utils/helpers/dataLayerUtils";

import { useLoginPasswordManager } from "../hooks/useLoginPasswordManager";

function Footer() {
  const { signupLink, texts, locales } = useLoginPasswordManager();

  if (!signupLink) {
    return null;
  }

  return (
    <div className="text-center">
      <span className="pr-1 text-body-text text-(length:--ul-theme-font-body-text-size) font-body">
        {texts?.signupActionText || locales?.footer?.signupActionText}
      </span>
      <ULThemeLink
        href={signupLink}
        onClick={() => {
          const linkText =
            texts?.signupActionLinkText ||
            locales?.footer?.signupActionLinkText ||
            "Regístrate";
          pushClicHipervinculo(
            `Crear cuenta - ${linkText}`,
            "/login-normal",
            getCanalByClientId()
          );
        }}
      >
        {texts?.signupActionLinkText || locales?.footer?.signupActionLinkText}
      </ULThemeLink>
    </div>
  );
}

export default Footer;
