import { useRef } from "react";
import { useForm } from "react-hook-form";

import { useErrors } from "@auth0/auth0-acul-react/mfa-sms-enrollment";
import type { ErrorItem } from "@auth0/auth0-acul-react/types";

import {
  ULThemeStaticLabelField,
} from "@/components/form";
import { Form, FormField, FormItem } from "@/components/ui/form";
import { ULThemeButton } from "@/components/ULThemeButton";
import ULThemeCountryCodePicker from "@/components/ULThemeCountryCodePicker";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import { transformAuth0CountryCode } from "@/utils/helpers/countryUtils";

import { useMfaSmsEnrollmentManager } from "../hooks/useMfaSmsEnrollmentManager";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushMfaSmsContinuar } from "@/utils/helpers/dataLayerUtils";

interface MfaSmsEnrollmentFormData {
  phone: string;
}

function MfaSmsEnrollmentForm() {
  const {
    handleContinueEnrollment,
    texts,
    locales,
    countryCode,
    countryPrefix,
  } = useMfaSmsEnrollmentManager();

  // Initialize the form using react-hook-form
  const form = useForm<MfaSmsEnrollmentFormData>({
    defaultValues: {
      phone: "",
    },
  });

  const {
    formState: { isSubmitting, errors: formErrors },
  } = form;

  // Use locales as fallback to SDK texts
  const buttonText = texts?.buttonText || locales?.buttonText;
  const phoneLabelText = texts?.placeholder || locales?.placeholder;
  const sendingText = locales?.buttonText;
  const selectCountryPlaceholder = locales?.selectCountryCode;

  const { errors, hasError, dismiss } = useErrors();

  // Get field-specific SDK errors
  const phoneErrors = errors.byField("phone") || [];
  const phoneSDKError = phoneErrors[0]?.message;

  // Get general errors (not field-specific)
  const generalErrors: ErrorItem[] = errors
    .byType("auth0")
    .filter((err) => !err.field);

  const errorsToTrack = [...generalErrors, ...phoneErrors];

  const isEnterRef = useRef(false);

  const onSubmit = async (formData: MfaSmsEnrollmentFormData) => {
    const canal = getCanalByClientId() || 'Coppel.com';
    const interaction = isEnterRef.current ? 'Enter' : 'Continuar';
    pushMfaSmsContinuar(interaction, '/protege-tu-cuenta/sms', canal);
    isEnterRef.current = false; // Reset
    await handleContinueEnrollment(formData.phone);
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-2">
        {/* Display general errors */}
        {hasError && errorsToTrack.length > 0 && (
          <div className="space-y-3 mb-4">
            {errorsToTrack.map((error) => (
              <ULThemeAlert
                key={error.id}
                variant="destructive"
                onDismiss={() => dismiss(error.id)}
              >
                <ULThemeAlertTitle>
                  {error.message || locales?.["sms-authenticator-error"]}
                </ULThemeAlertTitle>
              </ULThemeAlert>
            ))}
          </div>
        )}

        <div className="space-y-1">
          <label className="text-sm font-medium text-(--coppel-color-text-dark) mb-1 block">Celular</label>
          <div className="flex gap-2 items-start">
            {/* Country Code Picker */}
            <div className="w-[104px] flex-shrink-0">
              <ULThemeCountryCodePicker
                selectedCountry={transformAuth0CountryCode(
                  countryCode,
                  countryPrefix
                )}
                fullWidth
                compact
                disabled
                placeholder={selectCountryPlaceholder}
                className="h-14 opacity-100 bg-white px-2 border-[#E0E0E0]"
              />
            </div>

            {/* Phone Number input field */}
            <div className="flex-1">
              <FormField
                control={form.control}
                name="phone"
                rules={{
                  required: locales?.["no-phone"],
                }}
                render={({ field }) => (
                  <FormItem>
                    <ULThemeStaticLabelField
                      {...field}
                      label=""
                      placeholder={phoneLabelText}
                      type="tel"
                      inputMode="numeric"
                      autoComplete="tel"
                      autoFocus
                      error={false}
                      wrapperClassName="[&>label]:!text-(--coppel-color-text-dark)"
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          isEnterRef.current = true;
                        }
                      }}
                    />
                  </FormItem>
                )}
              />
            </div>
          </div>
          {/* Custom error message styling to match mfa-otp-enrollment */}
          {(formErrors.phone || phoneSDKError) && (
            <div className="text-[#D32F2F] text-sm mt-1 text-center w-full">
              {phoneSDKError || formErrors.phone?.message}
            </div>
          )}
        </div>

        {/* Submit button */}
        <ULThemeButton
          type="submit"
          variant="primary"
          className="w-full"
          disabled={isSubmitting}
        >
          {isSubmitting ? sendingText : buttonText}
        </ULThemeButton>
      </form>
    </Form>
  );
}

export default MfaSmsEnrollmentForm;
