import { useResend } from "@auth0/auth0-acul-react/mfa-sms-challenge";

import { ULThemeButton } from "@/components/ULThemeButton";

import { useMfaSmsChallengeManager } from "../hooks/useMfaSmsChallengeManager";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushMfaSmsChallengeIntentarOtroMetodo, pushMfaSmsChallengeReenviar } from "@/utils/helpers/dataLayerUtils";

function Footer() {
  const {
    texts,
    data,
    handleResendCode,
    handleGetACall,
    handleTryAnotherMethod,
    locales,
  } = useMfaSmsChallengeManager();

  // Use the resend hook for managing cooldown
  const { remaining, disabled } = useResend({
    timeoutSeconds: 30,
  });

  const resendText = texts?.resendText || locales.resendText;
  const resendLinkText =
    texts?.resendActionText || locales.resendActionText;
  const getCallText =
    texts?.resendVoiceActionText || locales.resendVoiceActionText;
  const separatorText =
    texts?.resendVoiceActionSeparatorTextBefore ||
    locales.resendVoiceActionSeparatorTextBefore;
  const tryAnotherMethodText =
    texts?.pickAuthenticatorText || locales.pickAuthenticatorText;

  const isEnrollmentVerify = window.location.pathname.includes("mfa-sms-enrollment-verify");;

  const handleResendClick = async () => {
    const canal = getCanalByClientId() || 'Coppel.com';
    const pagePath = isEnrollmentVerify ? '/protege-tu-cuenta/sms-codigo' : '/protege-tu-cuenta/celular';
    pushMfaSmsChallengeReenviar(pagePath, canal);
    
    await handleResendCode();
  };

  const handleGetCallClick = async () => {
    await handleGetACall();
  };

  const handleTryAnotherMethodClick = async () => {
    const canal = getCanalByClientId() || 'Coppel.com';
    const pagePath = isEnrollmentVerify ? '/protege-tu-cuenta/sms-codigo' : '/protege-tu-cuenta/celular';
    pushMfaSmsChallengeIntentarOtroMetodo(pagePath, canal);
    
    await handleTryAnotherMethod();
  };

  return (
    <div className="text-center mt-4">
      {/* Resend code link with optional get a call */}
      <div className="mb-2">
        <span className="text-(length:--ul-theme-font-body-text-size) font-body">
          {resendText}{" "}
        </span>
        <ULThemeButton
          onClick={handleResendClick}
          variant="link"
          size="link"
          disabled={disabled}
        >
          {disabled ? `${resendLinkText} en ${remaining}s` : resendLinkText}
        </ULThemeButton>
        {data?.showLinkVoice && (
          <>
            <span className="text-(length:--ul-theme-font-body-text-size) font-body">
              {" "}
              {separatorText}{" "}
            </span>
            <ULThemeButton
              onClick={handleGetCallClick}
              variant="link"
              size="link"
            >
              {getCallText}
            </ULThemeButton>
          </>
        )}
      </div>

      {/* Try another method link */}
      {isEnrollmentVerify && (
        <div>
          <ULThemeButton
            onClick={handleTryAnotherMethodClick}
            variant="link"
            size="link"
          >
            {tryAnotherMethodText}
          </ULThemeButton>
        </div>
      )}
    </div>
  );
}

export default Footer;
