import { useEffect } from "react";

import CoppelPageLayout from "@/components/CoppelPageLayout";
import ULThemeCard from "@/components/ULThemeCard";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushPageView } from "@/utils/helpers/dataLayerUtils";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import Details from "./components/Details";
import Footer from "./components/Footer";
import Header from "./components/Header";
import { usePasskeyEnrollmentManager } from "./hooks/usePasskeyEnrollmentManager";

function PasskeyEnrollmentScreen() {
  // Extracting attributes from hook made out of PasskeyEnrollmentInstance class of Auth0 React ACUL SDK
  const { passkeyEnrollmentInstance, locales } = usePasskeyEnrollmentManager();

  // Apply theme from SDK instance when screen loads
  applyAuth0Theme(passkeyEnrollmentInstance);

  useEffect(() => {
    const canal = getCanalByClientId() || "Coppel.com";
    pushPageView("/crear-llave-digital", "Crear llave digital", canal);
  }, []);

  return (
    // Applying UDS theme overrides using the "theme-universal" class
    <CoppelPageLayout
      className="theme-universal"
      pageTitle={locales?.page?.title}
    >
      <ULThemeCard className="w-full max-w-[400px] gap-0">
        <Header />
        <Details />
        <Footer />
      </ULThemeCard>
    </CoppelPageLayout>
  );
}

export default PasskeyEnrollmentScreen;
