import ULThemeSubtitle from "@/components/ULThemeSubtitle";
import ULThemeTitle from "@/components/ULThemeTitle";

import { useMfaSmsChallengeManager } from "../hooks/useMfaSmsChallengeManager";

function Header() {
  const { texts, locales } = useMfaSmsChallengeManager();

  // Handle text fallbacks in component
  const title = texts?.title || locales.title;
  const description = texts?.description || locales.description;

  return (
    <>
      <ULThemeTitle className="mb-4">{title}</ULThemeTitle>
      <ULThemeSubtitle className="mb-6 text-center">
        {description}
      </ULThemeSubtitle>
    </>
  );
}

export default Header;
