import { useEffect, useRef } from "react";
import { useForm } from "react-hook-form";

import type {
  ErrorItem,
  ResetPasswordRequestOptions,
} from "@auth0/auth0-acul-react/types";

import Captcha from "@/components/Captcha/index";
import { ULThemeStaticLabelField } from "@/components/form";
import { Form, FormField, FormItem } from "@/components/ui/form";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import { useCaptcha } from "@/hooks/useCaptcha";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import {
  pushErrorGeneral,
  pushResetPasswordRequestContinuar,
} from "@/utils/helpers/dataLayerUtils";
import { getIdentifierDetails } from "@/utils/helpers/identifierUtils";

import { useResetPasswordRequestManager } from "../hooks/resetPasswordRequestManager";
function ResetPasswordRequestForm() {
  const {
    handleResetPasswordRequest,
    texts,
    isCaptchaAvailable,
    captcha,
    activeIdentifiers,
    useErrors,
    locales,
    inputfield,
  } = useResetPasswordRequestManager();
  const { errors, hasError, dismiss } = useErrors;

  // Initialize the form using react-hook-form
  const form = useForm<ResetPasswordRequestOptions>({
    defaultValues: {
      username: String(inputfield).replace("+52", ""),
      captcha: "",
    },
  });

  const {
    formState: { isSubmitting },
    watch,
  } = form;

  const usernameValue = watch("username") ?? "";
  const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(usernameValue);
  const isValidPhone = /^\+?[1-9]\d{9}$/.test(usernameValue);
  const isFormValid = isValidEmail || isValidPhone;

  const buttonText = texts?.buttonText || locales.form.button;
  const captchaLabel = texts?.captchaCodePlaceholder
    ? `${texts.captchaCodePlaceholder}*`
    : `${locales.form.fields.captcha.label}*`;
  const identifierDetails = getIdentifierDetails(
    activeIdentifiers,
    texts,
    false
  );

  // Extract general errors (not field-specific) from the SDK
  const generalErrors: ErrorItem[] =
    errors.byType("auth0")?.filter((error) => {
      return !error.field || error.field === null;
    }) || [];

  const usernameErrors = errors.byField("username") || [];
  const captchaErrors = errors.byField("captcha") || [];

  const usernameSDKError = usernameErrors[0]?.message;
  const captchaSDKError = captchaErrors[0]?.message;

  const errorsToTrack = [...generalErrors, ...usernameErrors, ...captchaErrors];

  // Path para eventos de error
  const PAGE_ERROR_PATH = "/recuperacion-contrasena";

  // Rastrear errores ya taggeados para no duplicar eventos
  const taggedErrorIds = useRef<Set<string>>(new Set());

  // Rastrear si el envío fue por Enter o por clic en Continuar
  const submissionType = useRef<"Continuar" | "Enter">("Continuar");

  // dataLayer: disparar mensajeErrorGeneral cuando aparecen errores nuevos
  useEffect(() => {
    if (!hasError || errorsToTrack.length === 0) return;
    errorsToTrack.forEach((error) => {
      if (!taggedErrorIds.current.has(error.id)) {
        taggedErrorIds.current.add(error.id);
        pushErrorGeneral(
          PAGE_ERROR_PATH,
          error.id,
          error.message,
          getCanalByClientId()
        );
      }
    });
  }, [errorsToTrack, hasError]);

  const { captchaConfig, captchaProps, captchaValue } = useCaptcha(
    captcha || undefined,
    captchaLabel
  );

  const onSubmit = async (formData: ResetPasswordRequestOptions) => {
    const canal = getCanalByClientId();
    let formattedUsername = formData.username.trim();

    if (isValidPhone && !formattedUsername.startsWith("+")) {
      formattedUsername = `+52${formattedUsername}`;
    }

    const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formattedUsername);
    const cuentaTipo = isEmail ? "Correo" : "Celular";

    // Guardar el tipo de cuenta en sessionStorage para usarlo en la pantalla de éxito
    sessionStorage.setItem("resetPasswordCuentaTipo", cuentaTipo);

    pushResetPasswordRequestContinuar(
      submissionType.current,
      "/recuperacion-contrasena",
      cuentaTipo,
      canal
    );
    await handleResetPasswordRequest(formattedUsername, captchaValue);
  };

  return (
    <Form {...form}>
      <div role="group" aria-label="Recuperar contraseña">
        <form
          onSubmit={form.handleSubmit(onSubmit)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              submissionType.current = "Enter";
            }
          }}
        >
          {/* General error messages */}
          {hasError && errorsToTrack.length > 0 && (
            <div
              className="space-y-3 mb-4"
              aria-live="polite"
              aria-atomic="true"
            >
              {errorsToTrack.map((error) => {
                const message = error.message?.replace(
                  " Los números de teléfono deben incluir el código del país.",
                  ""
                );

                if (!message) return null;

                return (
                  <ULThemeAlert
                    key={error.id}
                    variant="destructive"
                    onDismiss={() => dismiss(error.id)}
                  >
                    <ULThemeAlertTitle>{message}</ULThemeAlertTitle>
                  </ULThemeAlert>
                );
              })}
            </div>
          )}

          {/* Username or Email or Phone pre-filled input field */}
          <FormField
            control={form.control}
            name="username"
            render={({ field, fieldState }) => (
              <FormItem>
                <ULThemeStaticLabelField
                  {...field}
                  label={
                    locales.form.fields.username.label ||
                    identifierDetails.label
                  }
                  placeholder={
                    locales.form.fields.username.placeholder ||
                    "Escribe tu correo"
                  }
                  type={identifierDetails.type}
                  inputMode="text"
                  autoComplete={identifierDetails.autoComplete}
                  autoFocus
                  error={!!fieldState.error || !!usernameSDKError}
                  aria-invalid={!!fieldState.error || !!usernameSDKError}
                  aria-describedby="username-error"
                />
              </FormItem>
            )}
          />

          {/* CAPTCHA Box */}
          {isCaptchaAvailable && captchaConfig && (
            <Captcha
              control={form.control}
              name="captcha"
              captcha={captchaConfig}
              {...captchaProps}
              sdkError={captchaSDKError}
              rules={{
                required: locales.form.fields.captcha.required,
              }}
              className="mt-2 mb-4"
            />
          )}

          {/* Submit button */}
          <ULThemeButton
            type="submit"
            variant="primary"
            className="w-full mt-6"
            disabled={isSubmitting || !isFormValid}
            onClick={(e) => {
              if (isSubmitting || !isFormValid) {
                e.preventDefault();
                return;
              }

              // Si detail > 0, es un clic real (mouse/touch).
              // Si es 0, es un clic sintético generado por presionar Enter.
              if (e.nativeEvent.detail > 0) {
                submissionType.current = "Continuar";
              }
            }}
          >
            {isSubmitting ? `${locales.form.submittingState}...` : buttonText}
          </ULThemeButton>
        </form>
      </div>
    </Form>
  );
}

export default ResetPasswordRequestForm;
