import { useEffect } from "react";

import CoppelPageLayout from "@/components/CoppelPageLayout";
import ULThemeCard from "@/components/ULThemeCard";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushPageView } from "@/utils/helpers/dataLayerUtils";
import { applyAuth0Theme } from "@/utils/theme";

import Header from "./components/Header";
import { useResetPasswordSuccessManager } from "./hooks/resetPasswordSuccessManager";

function ResetPasswordSuccessScreen() {
  // Extracting attributes from hook made out of ResetPasswordSuccessInstance class of Auth0 React SDK
  const { resetPasswordSuccess, texts, locales } =
    useResetPasswordSuccessManager();

  const canal = getCanalByClientId();

  useEffect(() => {
    pushPageView(
      "/recuperacion-contrasena/cambiaste-contrasena",
      "Crea nueva contraseña - Cambiaste contraseña",
      canal
    );
  }, [canal]);

  // Apply theme from SDK instance when screen loads
  applyAuth0Theme(resetPasswordSuccess);
  document.title = texts?.pageTitle || locales.pageTitle;

  return (
    // Applying UDS theme overrides using the "theme-universal" class
    <CoppelPageLayout
      className="theme-universal"
      pageTitle={texts?.pageTitle || locales.pageTitle}
    >
      <div className="w-full max-w-[400px] pt-20">
        <ULThemeCard className="!p-0 bg-card text-card-foreground shadow-bevel-2xl flex flex-col rounded-4xl min-w-[360px] theme-universal:bg-widget-bg theme-universal:border-(--color-widget-border) theme-universal:rounded-widget theme-universal:shadow-widget theme-universal:border-(length:--border-widget) w-full gap-0">
          <Header />
        </ULThemeCard>
      </div>
    </CoppelPageLayout>
  );
}

export default ResetPasswordSuccessScreen;
