import { useEffect, useRef } from "react";
import { useForm } from "react-hook-form";

import type {
  ErrorItem,
  PhoneChallengeOptions,
} from "@auth0/auth0-acul-react/types";

import { ULThemeStaticLabelField } from "@/components/form";
import { Form, FormField, FormItem } from "@/components/ui/form";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import {
  pushPhoneIdentifierContinuar,
  pushErrorGeneral,
} from "@/utils/helpers/dataLayerUtils";

import { usePhoneIdentifierChallengeManager } from "../hooks/usePhoneIdentifierChallengeManager";

function PhoneIdentifierChallengeForm() {
  const { handleSubmitPhoneChallenge, useErrors, texts, locales } =
    usePhoneIdentifierChallengeManager();

  // Initialize the form using react-hook-form
  const form = useForm<PhoneChallengeOptions>({
    defaultValues: {
      code: "",
    },
  });

  const {
    formState: { isSubmitting },
    watch,
  } = form;

  const codeValue = watch("code");

  const buttonText = texts?.buttonText || locales.form.buttonLabelText;
  const codeLabelText = texts?.placeholder || locales.form.field.labelText;
  const { errors, hasError, dismiss } = useErrors;

  // Extract general errors (not field-specific) from the SDK
  const generalErrors: ErrorItem[] =
    errors.byType("auth0")?.filter((error) => {
      return !error.field || error.field === null;
    }) || [];

  const codeErrors = errors.byField("code") || [];
  const errorsToTrack = [...generalErrors, ...codeErrors];

  const codeSDKError = codeErrors[0]?.message;

  const PAGE_ERROR_PATH = "/recuperacion-contrasena/revisa-tu-celular";

  // Rastrear errores ya taggeados para no duplicar eventos en re-renders
  const taggedErrorIds = useRef<Set<string>>(new Set());

  // dataLayer: disparar mensajeErrorGeneral cuando aparecen errores nuevos
  useEffect(() => {
    if (!hasError || errorsToTrack.length === 0) return;
    errorsToTrack.forEach((error) => {
      if (!taggedErrorIds.current.has(error.id)) {
        taggedErrorIds.current.add(error.id);
        pushErrorGeneral(
          PAGE_ERROR_PATH,
          error.id,
          error.message || "Error",
          getCanalByClientId()
        );
      }
    });
  }, [errorsToTrack, hasError]);

  const onSubmit = async (formData: PhoneChallengeOptions) => {
    const canal = getCanalByClientId();
    pushPhoneIdentifierContinuar(
      "/recuperacion-contrasena/revisa-tu-celular",
      canal
    );
    await handleSubmitPhoneChallenge(formData.code);
  };

  return (
    <Form {...form}>
      <div role="group" aria-label="Verificación de código telefónico">
        <form onSubmit={form.handleSubmit(onSubmit)}>
          {/* General error messages */}
          {hasError && errorsToTrack.length > 0 && (
            <div
              className="space-y-3 mb-4"
              aria-live="polite"
              aria-atomic="true"
            >
              {errorsToTrack.map((error) => (
                <ULThemeAlert
                  key={error.id}
                  variant="destructive"
                  onDismiss={() => dismiss(error.id)}
                >
                  <ULThemeAlertTitle>{error.message}</ULThemeAlertTitle>
                </ULThemeAlert>
              ))}
            </div>
          )}

          {/* Phone Code input field */}
          <FormField
            control={form.control}
            name="code"
            rules={{
              required: locales.form.field.required,
            }}
            render={({ field, fieldState }) => (
              <FormItem className="mb-6">
                <ULThemeStaticLabelField
                  {...field}
                  onChange={(e) => {
                    const value = e.target.value.replace(/\D/g, "");
                    field.onChange(value);
                  }}
                  maxLength={6}
                  label={`${codeLabelText}`}
                  type="text"
                  inputMode="numeric"
                  placeholder="Ingresa tu código"
                  autoComplete="one-time-code"
                  autoFocus
                  error={!!fieldState.error || !!codeSDKError}
                  aria-invalid={!!fieldState.error || !!codeSDKError}
                  aria-describedby="code-error"
                />
              </FormItem>
            )}
          />

          {/* Submit button */}
          <ULThemeButton
            type="submit"
            variant="primary"
            className="w-full mb-6"
            disabled={isSubmitting || codeValue?.length !== 6}
          >
            {isSubmitting
              ? `${locales.form.field.submitButtonText}`
              : buttonText}
          </ULThemeButton>
        </form>
      </div>
    </Form>
  );
}

export default PhoneIdentifierChallengeForm;
