import { ULThemeButton } from "@/components/ULThemeButton";

import { useMfaSmsEnrollmentManager } from "../hooks/useMfaSmsEnrollmentManager";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushMfaSmsIntentarOtroMetodo } from "@/utils/helpers/dataLayerUtils";

function Footer() {
  const { texts, locales, handleTryAnotherMethod } =
    useMfaSmsEnrollmentManager();

  // Use locales as fallback to SDK texts
  const tryAnotherMethodText =
    texts?.pickAuthenticatorText || locales?.pickAuthenticatorText;

  const handleTryAnotherMethodClick = async () => {
    const canal = getCanalByClientId() || 'Coppel.com';
    pushMfaSmsIntentarOtroMetodo('/protege-tu-cuenta/sms', canal);
    await handleTryAnotherMethod();
  };

  return (
    <div className="text-center space-y-2 mt-4">
      {/* Try another method link */}
      <ULThemeButton
        onClick={handleTryAnotherMethodClick}
        variant="link"
        size="link"
      >
        {tryAnotherMethodText}
      </ULThemeButton>
    </div>
  );
}

export default Footer;
