import { useEffect } from "react";

import ULThemeCard from "@/components/ULThemeCard";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushMfaSmsPageView } from "@/utils/helpers/dataLayerUtils";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import CoppelPageLayout from "../../components/CoppelPageLayout";

import Footer from "./components/Footer";
import Header from "./components/Header";
import MfaSmsEnrollmentForm from "./components/MfaSmsEnrollmentForm";
import { useMfaSmsEnrollmentManager } from "./hooks/useMfaSmsEnrollmentManager";

function MfaSmsEnrollmentScreen() {
  // Extracting attributes from hook made out of MfaSmsEnrollment instance of Auth0 React ACUL SDK
  const { mfaSmsEnrollment, texts, locales } = useMfaSmsEnrollmentManager();

  applyAuth0Theme(mfaSmsEnrollment);
  document.title = texts?.pageTitle || locales?.pageTitle;

  useEffect(() => {
    const canal = getCanalByClientId() || "Coppel.com";
    pushMfaSmsPageView(
      "/protege-tu-cuenta/sms",
      "Proteje tu cuenta - SMS",
      canal
    );
  }, []);

  return (
    <CoppelPageLayout
      className="theme-universal"
      pageTitle={texts?.pageTitle || locales?.pageTitle}
    >
      <div className="w-full flex justify-center items-start md:items-center min-h-[calc(100vh-118px)] py-8 md:py-0">
        <ULThemeCard className="w-full max-w-[400px] gap-0">
          <Header />
          <MfaSmsEnrollmentForm />
          <Footer />
        </ULThemeCard>
      </div>
    </CoppelPageLayout>
  );
}

export default MfaSmsEnrollmentScreen;
