import ULThemeLogo from "@/components/ULThemeLogo";
import ULThemeSubtitle from "@/components/ULThemeSubtitle";
import ULThemeTitle from "@/components/ULThemeTitle";

import { useMfaOtpChallengeManager } from "../hooks/useMfaOtpChallengeManager";

function Header({isPushOtpChallenge}: Readonly<{ isPushOtpChallenge: boolean }>) {
  const { texts, locales } = useMfaOtpChallengeManager();

  // Use Locales as fallback to SDK texts
  const titleText = texts?.title || locales.header.title;
  
  // Condicional para la descripción:
  const descriptionText = isPushOtpChallenge
    ? locales.header.descriptionPush
    : locales.header.description;

  const logoAltText = texts?.logoAltText || "Coppel Logo";

  return (
    <>
      <ULThemeLogo altText={logoAltText}></ULThemeLogo>
      <ULThemeTitle>{titleText}</ULThemeTitle>
      <ULThemeSubtitle className="mb-6">
        {descriptionText}
      </ULThemeSubtitle>
    </>
  );
}

export default Header;
