import { useEffect } from "react";

import CoppelPageLayout from "@/components/CoppelPageLayout";
import ULThemeCard from "@/components/ULThemeCard";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushPageView } from "@/utils/helpers/dataLayerUtils";
import { applyAuth0Theme } from "@/utils/theme";

import Header from "./components/Header";
import ResetPasswordForm from "./components/ResetPasswordForm";
import { useResetPasswordManager } from "./hooks/useResetPasswordManager";

function ResetPasswordScreen() {
  // Extracting attributes from hook made out of ResetPasswordInstance class of Auth0 React SDK
  const { resetPassword, texts, locales } = useResetPasswordManager();

  const canal = getCanalByClientId();

  useEffect(() => {
    pushPageView(
      "/recuperacion-contrasena/crea-nueva-contrasena",
      "Crea nueva contraseña",
      canal
    );
  }, [canal]);

  // Apply theme from SDK instance when screen loads
  applyAuth0Theme(resetPassword);

  return (
    // Applying UDS theme overrides using the "theme-universal" class
    <CoppelPageLayout
      className="theme-universal"
      pageTitle={texts?.pageTitle || locales.pageTitle}
    >
      <div className="w-full max-w-[400px] pt-20">
        <ULThemeCard className="w-full gap-6 p-[0px]">
          <Header />
          <ResetPasswordForm />
        </ULThemeCard>
      </div>
    </CoppelPageLayout>
  );
}

export default ResetPasswordScreen;
