import { useState } from "react";

import { useMfaOtpEnrollmentQr } from "@auth0/auth0-acul-react/mfa-otp-enrollment-qr";

import locales from "@/screens/mfa-otp-enrollment-qr/locales/es.json";
import { executeSafely } from "@/utils/helpers/executeSafely";

export const useMfaOtpEnrollmentQRManager = () => {
  const hookResult = useMfaOtpEnrollmentQr() as any;
  const { screen, tenant, transaction } = hookResult;

  const [code, setCode] = useState("");
  const [error, setError] = useState<string | null>(null);

  const data = screen?.data;
  const qrCode = (data as any)?.qr_code;
  const secret = (data as any)?.secret;

  const handleCodeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setCode(e.target.value);
    setError(null);
  };

  const handleContinue = async () => {
    if (!code) {
      setError(locales["no-code"]);
      return;
    }

    if (code.length !== 6 || !/^\d+$/.test(code)) {
      setError(locales["invalid-otp-code-format"]);
      return;
    }

    try {
      await executeSafely("Continue MFA OTP Enrollment QR", () =>
        hookResult.continue({ code })
      );
    } catch (err: any) {
      console.error("Error continuing:", err);
      setError(locales["invalid-code"]);
    }
  };

  const handlePickAuthenticator = async () => {
    try {
      if (typeof hookResult.pickAuthenticator === "function") {
        await executeSafely("Try Another Method", () =>
          hookResult.pickAuthenticator()
        );
      } else if (typeof hookResult.tryAnotherMethod === "function") {
        await executeSafely("Try Another Method", () =>
          hookResult.tryAnotherMethod()
        );
      } else {
        console.warn("pickAuthenticator not supported directly on this screen");
      }
    } catch (err) {
      console.error("Error picking authenticator:", err);
    }
  };

  const handleTroubleScanning = async () => {
    try {
      if (typeof hookResult.troubleScanning === "function") {
        await executeSafely("Trouble Scanning", () =>
          hookResult.troubleScanning()
        );
      } else if (typeof hookResult.toggleView === "function") {
        await executeSafely("Toggle View", () => hookResult.toggleView());
      } else {
        console.warn("troubleScanning not supported directly on this screen");
      }
    } catch (err) {
      console.error("Error showing secret:", err);
    }
  };

  // Extract errors from transaction if any
  const transactionErrors = transaction?.errors || [];
  const displayError =
    error ||
    (transactionErrors.length > 0
      ? (locales as any)[transactionErrors[0].code] ||
        transactionErrors[0].message
      : null);

  return {
    locales,
    qrCode,
    secret,
    code,
    error: displayError,
    handleCodeChange,
    handleContinue,
    handlePickAuthenticator,
    handleTroubleScanning,
    pickAuthenticatorEnabled: (tenant as any)?.mfa_options
      ?.pick_authenticator_enabled,
  };
};
