/**
 * Cuenta creada exitosamente.
 * ⚠️  La ubicación exacta de esta llamada aún está por definir
 *     (depende del flujo configurado desde el tenant de Auth0).
 *     La función está lista para ser invocada en el punto correcto.
 *
 * event: 'crearCuentaConDatos'
 *
 * @param page       Path amigable de la página (ej. '/crear-cuenta')
 * @param cuentaTipo 'Correo'
 * @param userId     ID de usuario generado en la tabla maestra
 * @param canal      Canal detectado por getCanalByClientId()
 */
export function pushCrearCuentaConDatos(
  page: string,
  cuentaTipo: CuentaTipoForm,
  userId: string,
  canal: Canal
): void {
  push({
    interaccionNombre: "Creación de cuenta con éxito",
    page,
    cuentaTipo,
    userId,
    canal,
    event: "crearCuentaConDatos",
  });
}

/**
 * Llave digital (Passkey) creada exitosamente.
 * Se dispara al resolver exitosamente el registro de Passkey.
 *
 * event: 'crearCuentaConDatos'
 *
 * @param page       Path amigable de la página (ej. '/crear-llave-digital')
 * @param cuentaTipo 'Correo' o el tipo correspondiente
 * @param userId     ID de usuario obtenido del contexto de Auth0
 * @param canal      Canal detectado por getCanalByClientId()
 */
export function pushCrearLlaveDigitalConExito(
  page: string,
  cuentaTipo: CuentaTipoForm,
  userId: string,
  canal: Canal,
  callback?: () => void
): void {
  push({
    interaccionNombre: "Creación de llave digital con éxito",
    page,
    cuentaTipo,
    userId,
    canal,
    event: "crearCuentaConDatos",
    eventCallback: callback,
    eventTimeout: 500, // Timeout de respaldo para GTM
  });
}

