import { useEffect } from "react";
import { useForm } from "react-hook-form";

import {
  useErrors,
  useMfaPolling,
} from "@auth0/auth0-acul-react/mfa-push-enrollment-qr";
import { type CustomOptions, ErrorItem } from "@auth0/auth0-acul-react/types";

import { Form } from "@/components/ui/form";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import {
  pushMfaEnrollOption,
  pushPageView,
} from "@/utils/helpers/dataLayerUtils";

import { useMfaPushEnrollmentQRManager } from "../hooks/useMfaPushEnrollmentQRManager";

function MfaPushEnrollmentQRForm() {
  const {
    data,
    texts,
    locales,
    handlePickAuthenticator,
    handleContinueMfaPushEnrollmentQR,
  } = useMfaPushEnrollmentQRManager();

  // Initialize the form using react-hook-form
  const form = useForm<CustomOptions>({});
  const { qrCode, qrUri, showCodeCopy } = data || {};

  // Use Locales as fallback to SDK texts
  const copyAsCodeLinkText =
    texts?.copyCodeLinkText || locales.form.copyCodeLinkText;
  const pickAuthenticatorText =
    texts?.pickAuthenticatorText || locales.form.pickAuthenticatorText;
  const shouldShowTryAnotherMethod = true;

  const { errors, hasError, dismiss } = useErrors();

  // Get general errors (not field-specific)
  const generalErrors: ErrorItem[] = errors
    .byType("auth0")
    .filter((err) => !err.field);
  const errorsToTrack = [...generalErrors];

  // Automatically start polling when the page loads
  const { startPolling, stopPolling } = useMfaPolling({
    intervalMs: 3000,
    onCompleted: () => {
      handleContinueMfaPushEnrollmentQR();
    },
    onError: (error: any) => {
      console.error("Push Enrollment Polling error:", error);

      // Si el ticket expira o da error 400, debemos detener el polling para evitar el loop infinito.
      // Puedes validar por código de error de polling.
      if (error?.code === "polling_error_400") {
        stopPolling();
      }
    },
  });

  useEffect(() => {
    pushPageView(
      "/protege-tu-cuenta/auth0-qr",
      "Protege tu cuenta - Auth0 QR",
      getCanalByClientId()
    );
  }, []);

  const handleCopyAsCode = (event: React.MouseEvent) => {
    event.preventDefault();
    if (qrUri) {
      navigator.clipboard
        .writeText(qrUri)
        .then(() => {
          pushMfaEnrollOption(
            "Copiar como codigo",
            "/protege-tu-cuenta/auth0-qr",
            getCanalByClientId()
          );
        })
        .catch((err) => {
          console.error("Could not copy text: ", err);
        });
    }
  };

  useEffect(() => {
    // No inicia el polling si estamos en desarrollo
    if (import.meta.env.DEV) {
      console.log("Polling detenido por desarrollo local");
    } else {
      console.log("Polling iniciado esperando escaneo del qr");
      startPolling();
    }

    return () => {
      console.log("Deteniendo Polling");
      stopPolling();
    };
  }, [startPolling, stopPolling]);

  return (
    <Form {...form}>
      <form>
        {/* General error messages */}
        {hasError && errorsToTrack.length > 0 && (
          <div className="space-y-3 mb-4">
            {errorsToTrack.map((error: ErrorItem) => {
              let displayMessage = error.message;
              if (
                error.code === "polling_error_400" ||
                (typeof displayMessage === "string" &&
                  displayMessage.includes("The transaction has expired"))
              ) {
                displayMessage = locales.errors.transactionExpired;
              }
              return (
                <ULThemeAlert
                  key={error.id}
                  variant="destructive"
                  onDismiss={() => dismiss(error.id)}
                >
                  <ULThemeAlertTitle>
                    {displayMessage || locales.errors.errorOccurred}
                  </ULThemeAlertTitle>
                </ULThemeAlert>
              );
            })}
          </div>
        )}

        <div className="text-center">
          {/* QR Code Image */}
          <div className="flex justify-center">
            <img
              alt={locales.form?.qrAlt}
              src={qrCode}
              className="border rounded-[3px] border-(--ul-theme-color-qrcode-border) w-45 h-45"
            />
          </div>
          {/* Copy QR As Code Button */}
          {showCodeCopy && (
            <ULThemeButton
              variant="primary"
              className="w-full mt-6"
              onClick={(event) => handleCopyAsCode(event)}
            >
              {copyAsCodeLinkText}
            </ULThemeButton>
          )}
        </div>
      </form>
      {/* Try another method link */}
      {shouldShowTryAnotherMethod && (
        <ULThemeButton
          onClick={() => {
            pushMfaEnrollOption(
              "Intentar con otro metodo",
              "/protege-tu-cuenta/auth0-qr",
              getCanalByClientId()
            );
            handlePickAuthenticator();
          }}
          variant="link"
          size="link"
          className="mt-4.5 text-center"
        >
          {pickAuthenticatorText}
        </ULThemeButton>
      )}
    </Form>
  );
}

export default MfaPushEnrollmentQRForm;
