import {
  useMfaOtpChallenge,
  useScreen,
} from "@auth0/auth0-acul-react/mfa-otp-challenge";
import {
  CustomOptions,
  MfaOtpChallengeMembers,
  ScreenMembersOnMfaOtpChallenge,
  WithRememberOptions,
} from "@auth0/auth0-acul-react/types";

import locales from "../locales/es.json";
import { executeSafely } from "@/utils/helpers/executeSafely";

export const useMfaOtpChallengeManager = () => {
  const screen: ScreenMembersOnMfaOtpChallenge = useScreen();
  const mfaOtpChallenge: MfaOtpChallengeMembers = useMfaOtpChallenge();

  const { texts, data, links } = screen;

  const handleContinue = async (
    payload: { code: string } & WithRememberOptions
  ): Promise<void> => {
    await executeSafely(
      `Continue MFA OTP Challenge with options: ${JSON.stringify(payload)}`,
      () => mfaOtpChallenge.continue(payload)
    );
  };

  const handleTryAnotherMethod = async (
    payload?: CustomOptions
  ): Promise<void> => {
    await executeSafely(
      "Switch to another MFA method",
      () => mfaOtpChallenge.tryAnotherMethod(payload)
    );
  };

  return {
    data,
    links,
    locales,
    mfaOtpChallenge,
    handleContinue,
    handleTryAnotherMethod,
    texts: (texts || {}) as ScreenMembersOnMfaOtpChallenge["texts"],
  };
};
