import { useEffect } from "react";
import { useForm } from "react-hook-form";

import {
  useErrors,
  useMfaPolling,
} from "@auth0/auth0-acul-react/mfa-push-challenge-push";
import type {
  ErrorItem,
  WithRememberOptions,
} from "@auth0/auth0-acul-react/types";

import { Form, FormField, FormItem } from "@/components/ui/form";
import { Label } from "@/components/ui/label";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeCheckbox } from "@/components/ULThemeCheckbox";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import ULThemeSeparator from "@/components/ULThemeSeparator";
import ULThemeSocialProviderButton from "@/components/ULThemeSocialProviderButton";
import ULThemeSpinner from "@/components/ULThemeSpinner";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushClicHipervinculo } from "@/utils/helpers/dataLayerUtils";

import { useMfaPushChallengeManager } from "../hooks/useMfaPushChallengeManager";

function MfaSmsChallengeForm() {
  const {
    data,
    texts,
    locales,
    handleEnterCodeManually,
    handleTryAnotherMethod,
    handleContinueMfaPushChallenge,
    handleResendPushNotification,
  } = useMfaPushChallengeManager();

  // Initialize the form using react-hook-form
  const form = useForm<WithRememberOptions>({
    defaultValues: {
      rememberDevice: false,
    },
  });

  // Use Locales as fallback to SDK texts
  const rememberDeviceText =
    texts?.rememberMeText || locales.form.rememberDeviceText;
  const enterOtpCodeText = texts?.enterOtpCode || locales.form.enterOtpCodeText;
  const resendText = texts?.resendText || locales.form.resendText;
  const resendLinkText =
    texts?.resendActionText || locales.form.resendActionText;
  const tryAnotherMethodText =
    texts?.pickAuthenticatorText || locales.form.tryAnotherMethodText;
  const { deviceName, showRememberDevice } = data || {};
  const separatorText = texts?.separatorText || locales.form.separatorText;
  const shouldShowTryAnotherMethod = false;

  const { errors, hasError, dismiss } = useErrors();

  // Get general errors (not field-specific)
  const generalErrors: ErrorItem[] = errors
    .byType("auth0")
    .filter((err) => !err.field);
  const errorsToTrack = [...generalErrors];

  // Automatically start polling when the page loads
  const { isRunning, startPolling, stopPolling } = useMfaPolling({
    intervalMs: 3000,
    onCompleted: () => {
      handleContinueMfaPushChallenge({
        rememberDevice: form.getValues().rememberDevice,
      });
    },
    onError: (error: unknown) => {
      console.error("Polling error:", error);
    },
  });

  const onResendActionClick = async (formData: WithRememberOptions) => {
    const canal = getCanalByClientId();
    pushClicHipervinculo(
      "Reenviar notificacion",
      "/protege-tu-cuenta/auth0-guardian",
      canal
    );
    await handleResendPushNotification(
      formData?.rememberDevice ? { rememberDevice: true } : {}
    );
  };

  useEffect(() => {
    // No inicia el polling si estamos en desarrollo
    if (import.meta.env.DEV) {
      console.log("Polling detenido por desarrollo local");
    } else {
      console.log("Polling iniciado esperando escaneo del qr");
      startPolling();
    }

    return () => {
      console.log("Deteniendo Polling");
      stopPolling();
    };
  }, [startPolling, stopPolling]);

  return (
    <Form {...form}>
      <form onSubmit={(e) => e.preventDefault()}>
        {/* General error messages */}
        {hasError && errorsToTrack.length > 0 && (
          <div className="space-y-3 mb-4">
            {errorsToTrack.map((error: ErrorItem) => {
              let displayMessage = error.message;
              if (
                error.code === "polling_error_400" ||
                (typeof displayMessage === "string" &&
                  displayMessage.includes("The transaction has expired"))
              ) {
                displayMessage = locales.errors.transactionExpired;
              }
              return (
                <ULThemeAlert
                  key={error.id}
                  variant="destructive"
                  onDismiss={() => dismiss(error.id)}
                >
                  <ULThemeAlertTitle>
                    {displayMessage || locales.errors.errorOccurred}
                  </ULThemeAlertTitle>
                </ULThemeAlert>
              );
            })}
          </div>
        )}

        {/* Disabled Device Name Field */}
        <FormField
          control={form.control}
          name="device"
          render={({ field }) => (
            <FormItem>
              <div
                tabIndex={0}
                aria-label={`${locales.form.ariaDeviceName} ${deviceName}`}
                // Opcional: Para que no se vea un recuadro feo al darle foco con el teclado,
                // pero mantenga la accesibilidad
                className="focus-visible:ring-2 focus-visible:ring-base-focus rounded-button"
              >
                <ULThemeSocialProviderButton
                  aria-hidden="true"
                  displayName={""}
                  key={deviceName}
                  buttonText={deviceName || locales.form.yourDeviceText}
                  iconComponent={isRunning && <ULThemeSpinner />}
                  disabled
                  name={field.name}
                  value={field.value as string | undefined}
                  className="theme-universal:border-input-border rounded-2xl theme-universal:rounded-input !justify-start !pl-4 bg-[var(--coppel-color-button-disabled-bg)] [&>span]:!text-left [&>span]:!text-[var(--coppel-color-text-disabled)]"
                  variant="ghost"
                />
              </div>
            </FormItem>
          )}
        />

        {/* Remember device checkbox */}
        {showRememberDevice && (
          <FormField
            control={form.control}
            name="rememberDevice"
            render={({ field }) => (
              <FormItem>
                <div className="flex items-center space-x-1 my-6 gap-1">
                  <ULThemeCheckbox
                    id="rememberDevice"
                    aria-labelledby="rememberDevice-label" // <-- Asocia con el label
                    checked={field.value}
                    onCheckedChange={field.onChange}
                    className="w-5 h-5 border-input-border"
                  />
                  <Label
                    id="rememberDevice-label" // <-- Le damos un id al label
                    htmlFor="rememberDevice"
                    className="text-(length:--ul-theme-font-body-text-size) cursor-pointer"
                  >
                    {rememberDeviceText}
                  </Label>
                </div>
              </FormItem>
            )}
          />
        )}

        <ULThemeSeparator text={separatorText} className="my-1" />

        <div className="flex flex-col items-center gap-6 mt-6">
          {/* Enter manual code button */}
          <ULThemeButton
            type="button"
            onClick={() => {
              const canal = getCanalByClientId();
              pushClicHipervinculo(
                "Ingresar codigo manualmente",
                "/protege-tu-cuenta/auth0-guardian",
                canal
              );
              handleEnterCodeManually();
            }}
            variant="secondary"
            className="w-full"
          >
            {enterOtpCodeText}
          </ULThemeButton>

          {/* Resend code link with optional get a call */}
          <div className="text-center">
            <span className="text-(length:--ul-theme-font-body-text-size) font-body">
              {resendText}{" "}
            </span>
            <ULThemeButton
              type="button"
              onClick={() =>
                onResendActionClick({
                  rememberDevice: Boolean(form.getValues().rememberDevice),
                })
              }
              variant="link"
              size="link"
            >
              {resendLinkText}
            </ULThemeButton>
          </div>

          {/* Try another method link */}
          {shouldShowTryAnotherMethod && (
            <ULThemeButton
              type="button"
              onClick={() => {
                const canal = getCanalByClientId();
                pushClicHipervinculo(
                  "Intentar con otro metodo",
                  "/protege-tu-cuenta/auth0-guardian",
                  canal
                );
                handleTryAnotherMethod();
              }}
              variant="link"
              size="link"
            >
              {tryAnotherMethodText}
            </ULThemeButton>
          )}
        </div>
      </form>
    </Form>
  );
}

export default MfaSmsChallengeForm;
