import { ULThemeButton } from "@/components/ULThemeButton";
import ULThemeTitle from "@/components/ULThemeTitle";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushResetPasswordSuccessIniciarSesion } from "@/utils/helpers/dataLayerUtils";

import { useResetPasswordSuccessManager } from "../hooks/resetPasswordSuccessManager";

function Header() {
  const { texts, locales, loginLink } = useResetPasswordSuccessManager();
  const title = texts?.eventTitle || locales.header.title;

  return (
    <>
      <div className="flex justify-center w-full mb-4">
        <svg
          width="76"
          height="76"
          viewBox="0 0 76 76"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          aria-hidden="true"
        >
          <path
            fillRule="evenodd"
            clipRule="evenodd"
            d="M38 76C58.9869 76 76 58.9869 76 38C76 17.0132 58.9869 0 38 0C17.0132 0 0 17.0132 0 38C0 58.9869 17.0132 76 38 76ZM57.0152 28.3291C58.4196 26.5732 58.1351 24.0112 56.379 22.6065C54.6234 21.2018 52.0612 21.4865 50.6565 23.2423L31.4074 47.3037L23.7072 41.5286C21.9083 40.1794 19.3563 40.544 18.0072 42.3429C16.6581 44.1417 17.0226 46.6937 18.8215 48.0429L29.6786 56.1857C31.4379 57.5054 33.927 57.1889 35.3008 55.4719L57.0152 28.3291Z"
            fill="#0ABF4F"
          />
        </svg>
      </div>
      <ULThemeTitle>{title}</ULThemeTitle>
      <ULThemeButton
        type="button"
        className="w-full mt-4"
        onClick={() => {
          // Recuperar el valor guardado o usar el fallback
          const cuentaTipo = sessionStorage.getItem("resetPasswordCuentaTipo") as "Correo" | "Celular" || "Correo";
          const canal = getCanalByClientId();
          pushResetPasswordSuccessIniciarSesion(
            "/recuperacion-contrasena/cambiaste-contrasena",
            cuentaTipo,
            canal
          );

          sessionStorage.removeItem("resetPasswordCuentaTipo");

          window.location.href = loginLink;
        }}
      >
        Iniciar sesión
      </ULThemeButton>
    </>
  );
}

export default Header;
