import { useEffect, useRef } from "react";
import { useForm } from "react-hook-form";

import { useErrors } from "@auth0/auth0-acul-react/mfa-sms-challenge";
import type {
  ErrorItem,
  MfaSmsChallengeOptions,
} from "@auth0/auth0-acul-react/types";

import { ULThemeStaticLabelField } from "@/components/form";
import { Form, FormField, FormItem } from "@/components/ui/form";
import { Label } from "@/components/ui/label";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeCheckbox } from "@/components/ULThemeCheckbox";
import ULThemeCountryCodePicker from "@/components/ULThemeCountryCodePicker";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { transformAuth0CountryCode } from "@/utils/helpers/countryUtils";
import {
  pushErrorGeneral,
  pushMfaSmsChallengeContinuar,
} from "@/utils/helpers/dataLayerUtils";

import { useMfaSmsChallengeManager } from "../hooks/useMfaSmsChallengeManager";

function MfaSmsChallengeForm() {
  const { handleContinueMfaSmsChallenge, data, texts, locales } =
    useMfaSmsChallengeManager();

  const { errors, hasError, dismiss } = useErrors();

  // Initialize the form using react-hook-form
  const form = useForm<MfaSmsChallengeOptions>({
    defaultValues: {
      code: "",
      rememberDevice: false,
    },
  });

  const {
    formState: { isSubmitting, errors: formErrors },
  } = form;

  const buttonText = texts?.buttonText || locales.buttonText;
  const codeLabelText = texts?.placeholder || locales.placeholder;
  const rememberDeviceText = texts?.rememberMeText || locales.rememberMeText;

  // Get field-specific errors using SDK's errors helper
  const codeErrors = errors.byField("code") || [];
  const codeSDKError = codeErrors[0]?.message;

  // Get general errors (errors without a specific field)
  const generalErrors: ErrorItem[] = errors
    .byType("auth0")
    .filter((err) => !err.field);

  const errorsToTrack = [...generalErrors, ...codeErrors];

  const isEnrollmentVerify = window.location.pathname.includes(
    "mfa-sms-enrollment-verify"
  );

  // Rastrear errores ya taggeados para no duplicar eventos en re-renders
  const taggedErrorIds = useRef<Set<string>>(new Set());

  useEffect(() => {
    const canal = getCanalByClientId() || "Coppel.com";
    const pagePath = isEnrollmentVerify
      ? "/protege-tu-cuenta/sms-codigo"
      : "/protege-tu-cuenta/celular";

    // Push combined errors to track
    if (hasError && errorsToTrack.length > 0) {
      errorsToTrack.forEach((error) => {
        if (!taggedErrorIds.current.has(error.id)) {
          taggedErrorIds.current.add(error.id);
          pushErrorGeneral(
            pagePath,
            error.id || "unknown_error",
            error.message ||
              locales?.["sms-authenticator-error"] ||
              "Error desconocido",
            canal
          );
        }
      });
    }

    // Push form validation errors (like empty code)
    if (formErrors.code) {
      const formErrorId = "required_code";
      if (!taggedErrorIds.current.has(formErrorId)) {
        taggedErrorIds.current.add(formErrorId);
        pushErrorGeneral(
          pagePath,
          formErrorId,
          formErrors.code.message ||
            locales["no-code"] ||
            "Por favor, introduzca un código",
          canal
        );
      }
    }
  }, [
    hasError,
    errorsToTrack,
    locales,
    isEnrollmentVerify,
    formErrors.code,
  ]);

  const maskedPhoneNumber = data?.phoneNumber || "XXXXXXXXX";
  const phoneNumberLabel = "Celular";

  // Extract country code and phone number from maskedPhoneNumber
  // Assuming format like "+52 55557948578" or similar
  let countryPrefix = "52"; // Default to 52 (without + because transformAuth0CountryCode adds it)
  let phoneWithoutPrefix = maskedPhoneNumber;

  if (maskedPhoneNumber.startsWith("+")) {
    const parts = maskedPhoneNumber.split(" ");
    if (parts.length > 1) {
      countryPrefix = parts[0].replace("+", "");
      phoneWithoutPrefix = parts.slice(1).join(" ");
    } else if (maskedPhoneNumber.startsWith("+52")) {
      // Handle case where there's no space: "+5255557948578"
      countryPrefix = "52";
      phoneWithoutPrefix = maskedPhoneNumber.substring(3);
    }
  }

  const isEnterRef = useRef(false);

  const onSubmit = async (formData: MfaSmsChallengeOptions) => {
    const canal = getCanalByClientId() || "Coppel.com";
    const interaction = isEnterRef.current ? "Enter" : "Continuar";
    const pagePath = isEnrollmentVerify
      ? "/protege-tu-cuenta/sms-codigo"
      : "/protege-tu-cuenta/celular";

    pushMfaSmsChallengeContinuar(interaction, pagePath, canal);

    isEnterRef.current = false; // Reset
    await handleContinueMfaSmsChallenge(formData.code, formData.rememberDevice);
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
        {/* General error messages */}
        {hasError && errorsToTrack.length > 0 && (
          <div className="space-y-3 mb-4">
            {errorsToTrack.map((error: ErrorItem) => (
              <ULThemeAlert
                key={error.id}
                variant="destructive"
                onDismiss={() => dismiss(error.id)}
              >
                <ULThemeAlertTitle>{error.message}</ULThemeAlertTitle>
              </ULThemeAlert>
            ))}
          </div>
        )}

        <div className="space-y-1">
          <label className="text-sm font-medium text-(--coppel-color-text-dark) mb-1 block">
            {phoneNumberLabel}
          </label>
          <div className="flex gap-2 items-start">
            {/* Country Code Picker */}
            {isEnrollmentVerify && (
              <div className="w-[104px] flex-shrink-0">
                <ULThemeCountryCodePicker
                  selectedCountry={transformAuth0CountryCode(
                    "MX", // Default to MX if we can't determine
                    countryPrefix
                  )}
                  fullWidth
                  compact
                  disabled
                  className="h-14 opacity-100 bg-white px-2 border-[#E0E0E0]"
                />
              </div>
            )}

            {/* Phone Number input field */}
            <div
              className={isEnrollmentVerify ? "w-[240px] relative" : "w-full"}
            >
              <ULThemeStaticLabelField
                name="phoneNumber"
                label=""
                value={
                  isEnrollmentVerify ? phoneWithoutPrefix : maskedPhoneNumber
                }
                disabled
                className="!bg-[#BDBDBD] !text-[#717171] !opacity-100"
              />
              {isEnrollmentVerify && (
                <button
                  type="button"
                  onClick={() => window.history.back()}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-sm font-semibold text-[#0045D8] hover:underline"
                >
                  Editar
                </button>
              )}
            </div>
          </div>
        </div>

        {/* SMS Code input field */}
        <FormField
          control={form.control}
          name="code"
          rules={{
            required: locales["no-code"],
          }}
          render={({ field, fieldState }) => (
            <FormItem>
              <ULThemeStaticLabelField
                {...field}
                label={codeLabelText}
                type="text"
                inputMode="numeric"
                placeholder=""
                autoComplete="one-time-code"
                autoFocus
                error={!!fieldState.error || !!codeSDKError}
                wrapperClassName="[&>label]:!text-(--coppel-color-text-dark)"
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    isEnterRef.current = true;
                  }
                }}
              />
            </FormItem>
          )}
        />

        {/* Remember device checkbox */}
        {data?.showRememberDevice && (
          <FormField
            control={form.control}
            name="rememberDevice"
            render={({ field }) => (
              <FormItem>
                <div className="flex items-center space-x-2 my-4">
                  <ULThemeCheckbox
                    id="rememberDevice"
                    checked={field.value}
                    onCheckedChange={field.onChange}
                  />
                  <Label
                    htmlFor="rememberDevice"
                    className="text-(length:--ul-theme-font-body-text-size) cursor-pointer"
                  >
                    {rememberDeviceText}
                  </Label>
                </div>
              </FormItem>
            )}
          />
        )}

        {/* Submit button */}
        <ULThemeButton
          type="submit"
          variant="primary"
          className="w-full"
          disabled={isSubmitting}
        >
          {isSubmitting ? "Verificando..." : buttonText}
        </ULThemeButton>
      </form>
    </Form>
  );
}

export default MfaSmsChallengeForm;
