import React, { useRef } from "react";
import { useForm } from "react-hook-form";

import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import {
  pushMfaOtpContinuar,
  pushMfaOtpIntentarOtroMetodo,
  pushMfaOtpProblemasAcceder,
} from "@/utils/helpers/dataLayerUtils";

import { ULThemeStaticLabelField } from "../../../components/form/ULThemeStaticLabelField";
import { Form, FormField, FormItem } from "../../../components/ui/form";
import { ULThemeButton } from "../../../components/ULThemeButton";
import ULThemeLink from "../../../components/ULThemeLink";
import ULThemeSeparator from "../../../components/ULThemeSeparator";
import ULThemeSubtitle from "../../../components/ULThemeSubtitle";
import ULThemeTitle from "../../../components/ULThemeTitle";
import { useMfaOtpEnrollmentQRManager } from "../hooks/useMfaOtpEnrollmentQRManager";

export const MfaOtpEnrollmentQRForm: React.FC = () => {
  const {
    locales,
    qrCode,
    code,
    error,
    handleCodeChange,
    handleContinue,
    handlePickAuthenticator,
    handleTroubleScanning,
  } = useMfaOtpEnrollmentQRManager();

  const form = useForm({
    defaultValues: {
      code: code || "",
    },
  });

  const isEnterRef = useRef(false);

  return (
    <div className="flex flex-col items-center w-full max-w-md mx-auto">
      <div className="text-center mb-2">
        <ULThemeTitle className="text-center">{locales.title}</ULThemeTitle>
        <ULThemeSubtitle className="whitespace-pre-line">
          {locales.description.replace(" 2-", "\n2-")}
        </ULThemeSubtitle>
      </div>

      {qrCode && (
        <div className="flex justify-center mb-4">
          <img src={qrCode} alt={locales.title} className="w-40 h-40" />
        </div>
      )}

      <div className="w-full text-center mb-2">
        <ULThemeLink
          href="#"
          onClick={(e: React.MouseEvent) => {
            e.preventDefault();
            const canal = getCanalByClientId() || "Coppel.com";
            pushMfaOtpProblemasAcceder(
              "/protege-tu-cuenta/google-autenticator",
              canal
            );
            handleTroubleScanning();
          }}
          className="text-sm font-semibold text-[#1C42E8]"
          aria-label={locales.codeEnrollmentText}
          role="button"
        >
          {locales.codeEnrollmentText}
        </ULThemeLink>
      </div>

      <ULThemeSeparator
        text={locales.separatorText}
        className="w-full [&_span]:!text-[#4A4A4A] [&_span]:!font-semibold my-2"
      />

      <div className="w-full space-y-4 mt-2">
        <Form {...form}>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              const canal = getCanalByClientId() || "Coppel.com";
              const interaction = isEnterRef.current ? "Enter" : "Continuar";
              pushMfaOtpContinuar(
                interaction,
                "/protege-tu-cuenta/google-autenticator",
                canal
              );
              handleContinue();
              isEnterRef.current = false; // Reset
            }}
            className="w-full space-y-4"
          >
            <FormField
              control={form.control}
              name="code"
              render={({ field }) => (
                <FormItem>
                  <div
                    className={
                      error
                        ? "[&_label]:!text-[#002D74] [&_input]:!text-[#002D74]"
                        : ""
                    }
                  >
                    <ULThemeStaticLabelField
                      {...field}
                      label={locales.placeholder}
                      value={code}
                      onChange={(e) => {
                        field.onChange(e);
                        handleCodeChange(e);
                      }}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          isEnterRef.current = true;
                        }
                      }}
                      placeholder={locales.placeholder}
                      error={!!error}
                      maxLength={6}
                    />
                  </div>
                  {error && (
                    <div className="text-[#D32F2F] text-sm mt-1 text-left">
                      {error}
                    </div>
                  )}
                </FormItem>
              )}
            />

            <ULThemeButton
              type="submit"
              className="w-full bg-[#0055FF] hover:bg-[#0044CC] text-white font-bold py-2 px-4 rounded"
            >
              {locales.buttonText}
            </ULThemeButton>
          </form>
        </Form>

        <div className="text-center mt-4">
          <ULThemeLink
            href="#"
            onClick={(e: React.MouseEvent) => {
              e.preventDefault();
              const canal = getCanalByClientId() || "Coppel.com";
              pushMfaOtpIntentarOtroMetodo(
                "/protege-tu-cuenta/google-autenticator",
                canal
              );
              handlePickAuthenticator();
            }}
            className="text-sm font-semibold text-[#1C42E8]"
            aria-label={locales.pickAuthenticatorText}
            role="button"
          >
            {locales.pickAuthenticatorText}
          </ULThemeLink>
        </div>
      </div>
    </div>
  );
};
