import ULThemeLink from "@/components/ULThemeLink";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushIniciarSesion } from "@/utils/helpers/dataLayerUtils";

import { useSignupPasswordManager } from "../hooks/useSignupPasswordManager";

function Footer() {
  const { loginLink, texts, locales } = useSignupPasswordManager();

  if (!loginLink) {
    return null;
  }

  // Use locale strings with fallback to SDK texts
  const footerText = locales.footer.text || texts?.footerText;
  const footerLinkText = locales.footer.linkText || texts?.footerLinkText;

  const handleLoginClick = () => {
    // dataLayer: evento clicClienteDigital al seleccionar "Inicia sesión"
    pushIniciarSesion("/crear-cuenta/crear-password", getCanalByClientId());
  };

  return (
    <div className="mt-4 text-center">
      <span className="pr-1 text-(--coppel-color-text-dark) text-(length:--ul-theme-font-body-text-size) font-body">
        {footerText}
      </span>
      {loginLink && (
        <ULThemeLink href={loginLink} onClick={handleLoginClick}>
          {footerLinkText}
        </ULThemeLink>
      )}
    </div>
  );
}

export default Footer;
