import { useState } from "react";

import { useMfaOtpEnrollmentCode } from "@auth0/auth0-acul-react/mfa-otp-enrollment-code";

import locales from "@/screens/mfa-otp-enrollment-code/locales/es.json";
import { executeSafely } from "@/utils/helpers/executeSafely";

export const useMfaOtpEnrollmentCodeManager = () => {
  const hookResult = useMfaOtpEnrollmentCode() as any;
  const { screen, tenant, transaction } = hookResult;

  const [code, setCode] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const data = screen?.data;
  const secret = (data as any)?.secret || (data as any)?.text_code;

  const handleCodeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setCode(e.target.value);
    setError(null);
  };

  const handleContinue = async () => {
    if (!code) {
      setError(locales["no-code"]);
      return;
    }

    if (code.length !== 6 || !/^\d+$/.test(code)) {
      setError(locales["invalid-otp-code-format"]);
      return;
    }

    try {
      await executeSafely("Continue MFA OTP Enrollment Code", () =>
        hookResult.continue({ code })
      );
    } catch (err: any) {
      console.error("Error continuing:", err);
      setError(locales["invalid-code"]);
    }
  };

  const handlePickAuthenticator = async () => {
    try {
      if (typeof hookResult.pickAuthenticator === "function") {
        await executeSafely("Try Another Method", () =>
          hookResult.pickAuthenticator()
        );
      } else if (typeof hookResult.tryAnotherMethod === "function") {
        await executeSafely("Try Another Method", () =>
          hookResult.tryAnotherMethod()
        );
      } else {
        console.warn("pickAuthenticator not supported directly on this screen");
      }
    } catch (err) {
      console.error("Error picking authenticator:", err);
    }
  };

  const handleScanQrCodeInstead = async () => {
    try {
      // The SDK doesn't expose toggleView on mfa-otp-enrollment-code, but we can manually submit the form
      // with the toggle-view action which is what the backend expects to switch back to the QR code view.
      const form = document.createElement("form");
      form.method = "POST";
      form.action = "";

      const stateInput = document.createElement("input");
      stateInput.type = "hidden";
      stateInput.name = "state";
      stateInput.value = transaction?.state || "";
      form.appendChild(stateInput);

      const actionInput = document.createElement("input");
      actionInput.type = "hidden";
      actionInput.name = "action";
      actionInput.value = "toggle-view";
      form.appendChild(actionInput);

      document.body.appendChild(form);
      form.submit();
    } catch (err) {
      console.error("Error toggling view:", err);
    }
  };

  const handleCopyCode = () => {
    if (secret) {
      navigator.clipboard.writeText(secret);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  // Extract errors from transaction if any
  const transactionErrors = transaction?.errors || [];
  const displayError =
    error ||
    (transactionErrors.length > 0
      ? (locales as any)[transactionErrors[0].code] ||
        transactionErrors[0].message
      : null);

  return {
    locales,
    secret,
    code,
    error: displayError,
    copied,
    handleCodeChange,
    handleContinue,
    handlePickAuthenticator,
    handleScanQrCodeInstead,
    handleCopyCode,
    pickAuthenticatorEnabled: (tenant as any)?.mfa_options
      ?.pick_authenticator_enabled,
  };
};
